DIAG = Path('/mnt/data/grizos_diagrams')
DIAG.mkdir(exist_ok=True)

# ---------- diagrams ----------
def render_dot(name, dot, width=None):
    p = DIAG / f'{name}.dot'
    png = DIAG / f'{name}.png'
    p.write_text(dot)
    subprocess.run(['dot','-Tpng','-Gdpi=180',str(p),'-o',str(png)], check=True)
    return png

