    'navy':'#20364F','teal':'#2D6F73','rust':'#A3573A','gold':'#A9833F','ink':'#222831',
    'light':'#F4F6F7','mid':'#DDE4E8','green':'#4F7C65','red':'#9B4A45','violet':'#665A7E'
}

