    return 'digraph G { graph [bgcolor="white", pad="0.2", nodesep="0.35", ranksep="0.45"]; node [shape=box, style="rounded,filled", fontname="Arial", fontsize=11, color="#9AA7B2", penwidth=1.1, margin="0.16,0.10"]; edge [fontname="Arial", fontsize=9, color="#6C7780", penwidth=1.2, arrowsize=0.75]; '

