digital [label="Digital collaborator / intelligence", fillcolor="#ECE9F3", color="{COL['violet']}"];
interaction [label="Interaction intelligence\nFast intent interpretation + interface composition\nNot the operating system", fillcolor="#E8F1F1", color="{COL['teal']}", penwidth=2];
os [label="GrizOS operating environment\nAuthority · state · context · routing · world model · capability access", fillcolor="#E9F0F4", color="{COL['navy']}", penwidth=2];
tools [label="Tools / specialized models\nSearch · perception · mapping · media · automation · transforms", fillcolor="{COL['light']}"];
sensors [label="Sensors / devices / external systems", fillcolor="{COL['light']}"];
