grizz [label="Grizz / GMRI attention\nInterrupt only when threshold justifies it", fillcolor="#FAECEA", color="{COL['red']}", penwidth=2];
ext -> prov -> delta -> stress -> triage -> receipt;
receipt -> grizz [label="brief / interrupt when warranted"];
receipt -> ext [style=dashed, label="continue watch"];
}}''')

render_dot('continuity_states', dot_header()+f'''
rankdir=LR;
conn [label="CONNECTED\nUse local + reachable remote capability", fillcolor="#EDF3EE", color="{COL['green']}", penwidth=2];
degr [label="DEGRADED\nA dependency is unavailable or stale\nPreserve useful function", fillcolor="#F7F1E7", color="{COL['gold']}", penwidth=2];
off [label="OFFLINE LOCAL\nApple-side core remains operational\nNo network assumption", fillcolor="#E9F0F4", color="{COL['navy']}", penwidth=2];
recover [label="RECOVERING\nDiagnose boundary of failure\nRejoin without interrupting local work", fillcolor="#E8F1F1", color="{COL['teal']}", penwidth=2];
recon [label="RECONCILING\nSync state, surface conflicts, preserve provenance", fillcolor="#F2EFE9", color="{COL['rust']}", penwidth=2];
conn -> degr [label="loss / fault"];
degr -> off [label="remote unavailable"];
off -> recover [label="connectivity returns"];
recover -> recon [label="service reachable"];
recon -> conn [label="state accepted"];
degr -> conn [style=dashed, label="fault cleared"];
recon -> off [style=dashed, label="recovery fails"];
}}''')

render_dot('authority_boundary', dot_header()+f'''
rankdir=TB;
info [label="Information authority\nRead · collect · classify · preserve", fillcolor="#EDF3EE"];
invest [label="Investigative authority\nPursue leads · test contradictions · deepen provenance", fillcolor="#E8F1F1"];
oper [label="Operational authority\nAlter external systems / files / communications\nExplicitly scoped", fillcolor="#F7F1E7"];
interrupt [label="Interruption authority\nBreak off-watch state only at defined thresholds", fillcolor="#FAECEA"];
final [label="Final-decision authority\nStrategic · public · legal · financial · high-consequence\nRetained by Grizz unless narrowly delegated", fillcolor="#F4E9EA", color="{COL['red']}", penwidth=2];
info -> invest -> oper -> interrupt -> final;
}}''')

# ---------- doc helpers ----------
doc = Document()
sec = doc.sections[0]
sec.top_margin = Inches(0.65); sec.bottom_margin = Inches(0.65); sec.left_margin = Inches(0.72); sec.right_margin = Inches(0.72)
sec.header_distance = Inches(0.28); sec.footer_distance = Inches(0.3)

# fonts & styles
styles = doc.styles
styles['Normal'].font.name = 'Aptos'; styles['Normal'].font.size = Pt(10.2)
styles['Normal'].paragraph_format.space_after = Pt(5.2)
styles['Normal'].paragraph_format.line_spacing = 1.08
for sname, size, color in [('Title',28,COL['navy']),('Subtitle',13,COL['teal']),('Heading 1',18,COL['navy']),('Heading 2',13.5,COL['teal']),('Heading 3',11.5,COL['rust'])]:
    st=styles[sname]; st.font.name='Aptos Display' if sname in ['Title','Heading 1','Heading 2'] else 'Aptos'; st.font.size=Pt(size); st.font.color.rgb=RGBColor.from_string(color.replace('#','')); st.font.bold=True if 'Heading' in sname or sname=='Title' else False
    if 'Heading' in sname:
        st.paragraph_format.space_before=Pt(10); st.paragraph_format.space_after=Pt(4)

# custom styles
for name, sz, bold, color in [('Small',8.6,False,COL['ink']),('Caption',8.5,False,'5D6871'),('Callout',10.2,False,COL['ink']),('Requirement',9.7,False,COL['ink'])]:
    if name not in styles:
        st=styles.add_style(name, WD_STYLE_TYPE.PARAGRAPH)
    else: st=styles[name]
    st.font.name='Aptos'; st.font.size=Pt(sz); st.font.bold=bold; st.font.color.rgb=RGBColor.from_string(color.replace('#',''))
    st.paragraph_format.space_after=Pt(4)

# page footer page number
footer = sec.footer.paragraphs[0]
footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
r=footer.add_run('GRIZZLYMEDICINE RESEARCH INSTITUTE  •  GrizOS PRD  •  '); r.font.size=Pt(8); r.font.color.rgb=RGBColor(110,120,130)
fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); footer._p.append(fld)

# helper funcs

def shade(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=tcPr.find(qn('w:shd'))
    if shd is None: shd=OxmlElement('w:shd'); tcPr.append(shd)
    shd.set(qn('w:fill'),fill.replace('#',''))

def set_cell_margin(cell, top=80, start=95, bottom=80, end=95):
    tc=cell._tc; tcPr=tc.get_or_add_tcPr(); tcMar=tcPr.first_child_found_in('w:tcMar')
    if tcMar is None:
        tcMar=OxmlElement('w:tcMar'); tcPr.append(tcMar)
    for m,v in [('top',top),('start',start),('bottom',bottom),('end',end)]:
        node=tcMar.find(qn('w:'+m))
        if node is None: node=OxmlElement('w:'+m); tcMar.append(node)
        node.set(qn('w:w'),str(v)); node.set(qn('w:type'),'dxa')

def set_repeat_table_header(row):
    trPr=row._tr.get_or_add_trPr(); tblHeader=OxmlElement('w:tblHeader'); tblHeader.set(qn('w:val'),'true'); trPr.append(tblHeader)

def set_keep_with_next(p):
    p.paragraph_format.keep_with_next=True

def add_label(text, fill='E9F0F4', color=COL['navy']):
    t=doc.add_table(rows=1, cols=1); t.alignment=WD_TABLE_ALIGNMENT.LEFT; t.autofit=False; t.columns[0].width=Inches(2.0)
    c=t.cell(0,0); shade(c,fill); set_cell_margin(c,55,90,55,90); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); r=p.add_run(text.upper()); r.bold=True; r.font.size=Pt(8.5); r.font.color.rgb=RGBColor.from_string(color.replace('#',''))
    return t

def add_callout(title, body, fill='F4F6F7', border='20364F'):
    t=doc.add_table(rows=1, cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False; t.columns[0].width=Inches(6.7)
    c=t.cell(0,0); shade(c,fill); set_cell_margin(c,110,140,110,140)
    tcPr=c._tc.get_or_add_tcPr(); borders=tcPr.first_child_found_in('w:tcBorders')
    if borders is None: borders=OxmlElement('w:tcBorders'); tcPr.append(borders)
    left=OxmlElement('w:left'); left.set(qn('w:val'),'single'); left.set(qn('w:sz'),'18'); left.set(qn('w:color'),border); borders.append(left)
    p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(2); r=p.add_run(title); r.bold=True; r.font.color.rgb=RGBColor.from_string(border)
    p2=c.add_paragraph(body, style='Callout'); p2.paragraph_format.space_after=Pt(0)
    doc.add_paragraph().paragraph_format.space_after=Pt(1)

def add_fig(path, caption, width=6.7):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(2)
    p.add_run().add_picture(str(path), width=Inches(width))
    cap=doc.add_paragraph(caption, style='Caption'); cap.alignment=WD_ALIGN_PARAGRAPH.CENTER; cap.paragraph_format.space_after=Pt(7)

def add_bullets(items, level=0):
    for item in items:
        p=doc.add_paragraph(style='List Bullet' if level==0 else 'List Bullet 2'); p.paragraph_format.space_after=Pt(2.5); p.add_run(item)

def add_numbered(items):
    for item in items:
        p=doc.add_paragraph(style='List Number'); p.paragraph_format.space_after=Pt(2.5); p.add_run(item)

def add_table(headers, rows, widths=None, font=8.8):
    t=doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'; t.autofit=False
    if widths:
        for i,w in enumerate(widths): t.columns[i].width=Inches(w)
    hdr=t.rows[0]; set_repeat_table_header(hdr)
    for i,h in enumerate(headers):
        c=hdr.cells[i]; shade(c,'20364F'); set_cell_margin(c,85,85,85,85); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        p=c.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(0); r=p.add_run(h); r.bold=True; r.font.color.rgb=RGBColor(255,255,255); r.font.size=Pt(font)
    for ridx,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            c=cells[i]; set_cell_margin(c,80,90,80,90); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if ridx%2==0: shade(c,'F7F8F9')
            p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.02
            r=p.add_run(str(val)); r.font.size=Pt(font); r.font.color.rgb=RGBColor.from_string(COL['ink'].replace('#',''))
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def page_break(): doc.add_page_break()

# ---------- Cover ----------
p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(70); p.alignment=WD_ALIGN_PARAGRAPH.LEFT
r=p.add_run('GRIZZLYMEDICINE\nRESEARCH INSTITUTE'); r.bold=True; r.font.size=Pt(11); r.font.color.rgb=RGBColor.from_string(COL['teal'].replace('#',''))
p=doc.add_paragraph(style='Title'); p.paragraph_format.space_before=Pt(42); p.paragraph_format.space_after=Pt(8)
p.add_run('GrizOS')
p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(4); r=p.add_run('Product Requirements & Experience Specification'); r.bold=True; r.font.size=Pt(19); r.font.color.rgb=RGBColor.from_string(COL['navy'].replace('#',''))
p=doc.add_paragraph(); r=p.add_run('User Interface · Spatial Environment · Dottie Hill'); r.font.size=Pt(13); r.font.color.rgb=RGBColor.from_string(COL['rust'].replace('#',''))

p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(56); p.paragraph_format.space_after=Pt(4)
r=p.add_run('Version 1.0  |  04 October 2026'); r.font.size=Pt(10.5); r.bold=True
p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(1); r=p.add_run('Status: Product baseline / implementation-agnostic requirements'); r.font.size=Pt(9.6); r.font.color.rgb=RGBColor(90,100,110)
p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(1); r=p.add_run('Scope excludes Project Sovereign internals.'); r.font.size=Pt(9.6); r.font.color.rgb=RGBColor(90,100,110)

add_callout('Design anchor', 'The environment exists to let biological and digital collaborators work in the same world without collapsing the boundaries between the operating system, the intelligence, and the tools.', 'EEF2F4','20364F')
page_break()

# ---------- Document map ----------
doc.add_heading('Document Map', level=1)
for idx, title in enumerate([
    'Product definition and governing principles',
    'Product family and context expressions',
    'Boundary architecture: OS, intelligence, tools, and peers',
    'Interaction model: voice → visual → touch → type',
    'Generative / intent-first UI and anti-DOM requirements',
    'Spatial environment and navigation',
    "God's Eye View integration and Bridge Crossing",
    'Dottie Hill: watch, authority, evidence, and embodiment',
